<?php require 'faculty_bootstrap.php';
$title='Faculty Dashboard';$fid=(int)$_SESSION['user']['id'];
$classes=$pdo->prepare("SELECT o.id,s.id subject_id,s.code,s.name,s.units,o.section,o.day_name,o.start_time,o.end_time,o.room,COUNT(DISTINCT CASE WHEN e.status='approved' THEN e.student_id END) student_count FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id LEFT JOIN enrollments e ON e.offering_id=o.id WHERE o.faculty_id=? GROUP BY o.id ORDER BY FIELD(o.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),o.start_time,s.code");$classes->execute([$fid]);$classes=$classes->fetchAll();
$pendingQ=$pdo->prepare("SELECT COUNT(*) FROM enrollments e JOIN subject_offerings o ON o.id=e.offering_id WHERE o.faculty_id=? AND e.status='pending'");$pendingQ->execute([$fid]);$pending=(int)$pendingQ->fetchColumn();
$studentQ=$pdo->prepare("SELECT COUNT(DISTINCT e.student_id) FROM enrollments e JOIN subject_offerings o ON o.id=e.offering_id WHERE o.faculty_id=? AND e.status='approved'");$studentQ->execute([$fid]);$students=(int)$studentQ->fetchColumn();
$today=date('l');$todayQ=$pdo->prepare("SELECT o.*,s.code,s.name FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.faculty_id=? AND o.day_name=? ORDER BY o.start_time");$todayQ->execute([$fid,$today]);$todayClasses=$todayQ->fetchAll();
$recentQ=$pdo->prepare("SELECT e.id,e.status,e.created_at,u.name student,s.code,s.name subject,o.section,o.day_name,o.start_time,o.end_time FROM enrollments e JOIN users u ON u.id=e.student_id JOIN subjects s ON s.id=e.subject_id JOIN subject_offerings o ON o.id=e.offering_id WHERE o.faculty_id=? ORDER BY e.created_at DESC LIMIT 5");$recentQ->execute([$fid]);$recent=$recentQ->fetchAll();
require 'header.php';faculty_flash_html();
?>
<div class="faculty-welcome"><div><span class="eyebrow">FACULTY PORTAL</span><h2>Welcome, <?=e($_SESSION['user']['name'])?></h2><p class="muted">Manage your classes, students, teaching schedule, and enrollment requests.</p></div><div class="faculty-quick"><a class="btn" href="faculty_classes.php">My Classes</a><a class="btn" href="faculty_attendance.php">Attendance</a><a class="btn" href="faculty_gradebook.php">Gradebook</a><a class="btn" href="faculty_enrollment.php">Enrollment Requests</a></div></div>
<div class="cards faculty-stat-cards"><div class="card stat"><span class="muted">ASSIGNED CLASSES</span><div class="num blue"><?=count($classes)?></div></div><div class="card stat"><span class="muted">STUDENTS</span><div class="num blue"><?=$students?></div></div><div class="card stat"><span class="muted">PENDING REQUESTS</span><div class="num purple"><?=$pending?></div></div><div class="card stat"><span class="muted">TODAY'S CLASSES</span><div class="num blue"><?=count($todayClasses)?></div></div></div>
<div class="faculty-dashboard-grid"><section class="section"><div class="card-head"><div><span class="eyebrow">TODAY</span><h2>Today's Teaching Schedule</h2></div><a class="small-link" href="faculty_schedule.php">View full schedule →</a></div><?php if(!$todayClasses):?><p class="muted">No classes assigned for <?=e($today)?>.</p><?php endif;?><?php foreach($todayClasses as $c):?><div class="list-row"><span><b><?=e($c['code'])?> — <?=e($c['name'])?></b><small><?=date('g:i A',strtotime($c['start_time']))?>–<?=date('g:i A',strtotime($c['end_time']))?> · Section <?=e($c['section'])?> · <?=e($c['room'])?></small></span><a class="small-link" href="faculty_classes.php?offering=<?=e($c['id'])?>">View class →</a></div><?php endforeach;?></section>
<section class="section"><div class="card-head"><div><span class="eyebrow">ACTIVITY</span><h2>Recent Enrollment Requests</h2></div><a class="small-link" href="faculty_enrollment.php">View all →</a></div><?php if(!$recent):?><p class="muted">No enrollment activity yet.</p><?php endif;?><?php foreach($recent as $r):?><div class="list-row"><span><b><?=e($r['student'])?></b><small><?=e($r['code'])?> · <?=e($r['section'])?> · <?=e($r['day_name'])?> <?=date('g:i A',strtotime($r['start_time']))?>–<?=date('g:i A',strtotime($r['end_time']))?></small></span><span class="badge <?=e($r['status'])?>"><?=ucfirst(e($r['status']))?></span></div><?php endforeach;?></section></div>
<section class="section"><div class="card-head"><div><span class="eyebrow">MY CLASSES</span><h2>Assigned Classes</h2></div><a class="small-link" href="faculty_classes.php">Manage classes →</a></div><div class="table-scroll"><table class="table"><tr><th>Subject</th><th>Section</th><th>Schedule</th><th>Room</th><th>Students</th></tr><?php foreach($classes as $c):?><tr><td><b><?=e($c['code'])?></b><br><?=e($c['name'])?></td><td><?=e($c['section'])?></td><td><?=e($c['day_name'])?><br><?=date('g:i A',strtotime($c['start_time']))?>–<?=date('g:i A',strtotime($c['end_time']))?></td><td><?=e($c['room'])?></td><td><?=e($c['student_count'])?></td></tr><?php endforeach;?></table></div></section>
<?php require 'footer.php';?>
